from collections import Counter
class Solution:
    def numberOfNodes(self, n: int, queries: List[int]) -> int:
        cnt = Counter(queries)
        state = [0] * (n + 1)
        for q, c in cnt.items():
            if c % 2 == 0:
                continue
            stack = [q]
            while stack:
                x = stack.pop()
                if x <= n:
                    state[x] ^= 1
                    stack.append(2 * x)
                    stack.append(2 * x + 1)
        return sum(state)

