class Solution {
public:
    int numberOfNodes(int n, vector<int>& queries) {
        unordered_map<int,int> cnt;
        for (int q : queries) cnt[q]++;
        vector<char> st(n + 1, 0);
        for (auto& [q, c] : cnt) {
            if (c % 2 == 0) continue;
            vector<int> stack{q};
            while (!stack.empty()) {
                int x = stack.back(); stack.pop_back();
                if (x <= n) {
                    st[x] ^= 1;
                    stack.push_back(2 * x);
                    stack.push_back(2 * x + 1);
                }
            }
        }
        int ans = 0;
        for (int v = 1; v <= n; v++) ans += st[v];
        return ans;
    }
};

