class Solution {
    public int numberOfNodes(int n, int[] queries) {
        Map<Integer,Integer> cnt = new HashMap<>();
        for (int q : queries) cnt.merge(q, 1, Integer::sum);
        int[] st = new int[n + 1];
        for (Map.Entry<Integer,Integer> e : cnt.entrySet()) {
            if (e.getValue() % 2 == 0) continue;
            Deque<Integer> stack = new ArrayDeque<>();
            stack.push(e.getKey());
            while (!stack.isEmpty()) {
                int x = stack.pop();
                if (x <= n) {
                    st[x] ^= 1;
                    stack.push(2 * x);
                    stack.push(2 * x + 1);
                }
            }
        }
        int ans = 0;
        for (int v = 1; v <= n; v++) ans += st[v];
        return ans;
    }
}

