    for (const q of queries) cnt.set(q, (cnt.get(q) || 0) + 1);
    const st = Array(n + 1).fill(0);
    for (const [q, c] of cnt) {
        if (c % 2 === 0) continue;
        const stack = [q];
        while (stack.length) {
            const x = stack.pop();
            if (x <= n) {
                st[x] ^= 1;
                stack.push(2 * x, 2 * x + 1);
            }
        }
    }
    return st.reduce((a, b) => a + b, 0);
