        cnt = Counter(queries)
        odd = {q for q, c in cnt.items() if c % 2}
        ans = 0
        for v in range(1, n + 1):
            x, p = v, 0
            while x:
                if x in odd:
                    p ^= 1
                x //= 2
            ans += p
        return ans

